param([Parameter(Mandatory=$true)][string]$BundleRoot,[Parameter(Mandatory=$true)][string]$InstallRoot,[Parameter(Mandatory=$true)][string]$TaskRoot,[Parameter(Mandatory=$true)][string]$EvidenceRoot)
$ErrorActionPreference='Stop'
$BundleRoot=[IO.Path]::GetFullPath($BundleRoot); $InstallRoot=[IO.Path]::GetFullPath($InstallRoot); $TaskRoot=[IO.Path]::GetFullPath($TaskRoot); $EvidenceRoot=[IO.Path]::GetFullPath($EvidenceRoot)
if(-not $InstallRoot.StartsWith($TaskRoot.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Install root is outside task temp.'}
if(-not $BundleRoot.StartsWith($TaskRoot.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Expanded bundle is outside task temp.'}
if(-not $EvidenceRoot.StartsWith('C:\maos\review-packets\committed-install-gui-validation-2026-10-29',[StringComparison]::OrdinalIgnoreCase)){throw 'Evidence root is outside the new packet.'}
foreach($p in @($InstallRoot,(Join-Path $TaskRoot 'isolated appdata with spaces'),(Join-Path $TaskRoot 'isolated localappdata with spaces'),(Join-Path $TaskRoot 'isolated user profile with spaces'),(Join-Path $TaskRoot 'empty npm cache'),(Join-Path $TaskRoot 'empty Electron cache'))){New-Item -ItemType Directory -Path $p -Force | Out-Null}
$files=@{NPM_CONFIG_USERCONFIG=(Join-Path $TaskRoot 'empty npm user config');NPM_CONFIG_GLOBALCONFIG=(Join-Path $TaskRoot 'empty npm global config')}
foreach($k in $files.Keys){Set-Content -LiteralPath $files[$k] -Value '' -NoNewline -Encoding ascii}
$node=(Get-Command node.exe -ErrorAction Stop).Source; $npm=(Get-Command npm.cmd -ErrorAction Stop).Source; $tar=(Get-Command tar.exe -ErrorAction Stop).Source
$originalPath=$env:PATH; $systemRoot=$env:SystemRoot; $pathBins=@((Split-Path -Parent $node),(Split-Path -Parent $tar), (Join-Path $systemRoot 'System32'),$systemRoot) | Select-Object -Unique
$removedSensitive=@(Get-ChildItem Env: | Where-Object {$_.Name -match '(?i)(API.?KEY|TOKEN|SECRET|PASSWORD|CREDENTIAL|AUTHORIZATION)' -or $_.Name -match '(?i)^ELECTRON_(MIRROR|CUSTOM_DIR)$' -or $_.Name -match '(?i)^NPM_CONFIG_(ELECTRON_MIRROR|PROXY|HTTPS_PROXY|HTTP_PROXY)$'})
foreach($item in $removedSensitive){Remove-Item -LiteralPath ('Env:'+ $item.Name) -ErrorAction SilentlyContinue}
$env:PATH=($pathBins -join ';'); $env:SystemRoot=$systemRoot; $env:WINDIR=$systemRoot; $env:OS='Windows_NT'; $env:PATHEXT='.COM;.EXE;.BAT;.CMD'
$env:APPDATA=Join-Path $TaskRoot 'isolated appdata with spaces'; $env:LOCALAPPDATA=Join-Path $TaskRoot 'isolated localappdata with spaces'; $env:USERPROFILE=Join-Path $TaskRoot 'isolated user profile with spaces'; $env:HOME=$env:USERPROFILE; $env:TEMP=Join-Path $TaskRoot 'install temp with spaces'; $env:TMP=$env:TEMP
New-Item -ItemType Directory -Path $env:TEMP -Force | Out-Null
$env:npm_config_cache=Join-Path $TaskRoot 'empty npm cache'; $env:NPM_CONFIG_USERCONFIG=$files.NPM_CONFIG_USERCONFIG; $env:NPM_CONFIG_GLOBALCONFIG=$files.NPM_CONFIG_GLOBALCONFIG; $env:NPM_CONFIG_REGISTRY='https://registry.npmjs.org/'; $env:ELECTRON_CACHE=Join-Path $TaskRoot 'empty Electron cache'; $env:GIT_CONFIG_NOSYSTEM='true'; $env:GIT_CONFIG_GLOBAL=Join-Path $TaskRoot 'empty git config'; Set-Content -LiteralPath $env:GIT_CONFIG_GLOBAL -Value '' -NoNewline -Encoding ascii
$env:GIT_CEILING_DIRECTORIES=$TaskRoot
$initialNpmCache=(Get-ChildItem -Force $env:npm_config_cache | Measure-Object).Count; $initialElectronCache=(Get-ChildItem -Force $env:ELECTRON_CACHE | Measure-Object).Count
$manifest=Get-Content -LiteralPath (Join-Path $BundleRoot 'bundle-manifest.json') -Raw | ConvertFrom-Json
$zip=Join-Path $EvidenceRoot 'candidate-artifacts/maos-industrial-bootstrap-windows-x64-commit-27dd1711-2026-10-29.zip'
$installScript=Join-Path $BundleRoot 'Install-MaosIndustrial.ps1'
$installStdout=Join-Path $EvidenceRoot 'clean-install.stdout.log'; $installStderr=Join-Path $EvidenceRoot 'clean-install.stderr.log'; $installCode=1
try { & $installScript -BundleRoot $BundleRoot -InstallRoot $InstallRoot *> $installStdout; $installCode=if($LASTEXITCODE -ne 0){$LASTEXITCODE}else{0} } catch { $_ | Out-String | Set-Content -LiteralPath $installStderr -Encoding utf8; $installCode=1 }
$log=@(); $log+=('INSTALL_EXIT_CODE='+$installCode); $log+=('NODE='+$node+' '+(& $node --version)); $log+=('NPM='+$npm+' '+(& $npm --version)); $log+=('TAR='+$tar); $log+=('SENSITIVE_ENV_NAMES_REMOVED='+$removedSensitive.Count); $log+=('INITIAL_NPM_CACHE_ENTRIES='+$initialNpmCache); $log+=('INITIAL_ELECTRON_CACHE_ENTRIES='+$initialElectronCache); $log+=('INSTALL_ROOT='+$InstallRoot); $log+=('USER_PROFILE='+$env:USERPROFILE); $log+=('NPM_CACHE='+$env:npm_config_cache); $log+=('ELECTRON_CACHE='+$env:ELECTRON_CACHE); $log | Set-Content -LiteralPath (Join-Path $EvidenceRoot 'clean-install-metadata.log') -Encoding utf8
$npmEntries=@(Get-ChildItem -Force $env:npm_config_cache -Recurse -File -ErrorAction SilentlyContinue).Count; $electronEntries=@(Get-ChildItem -Force $env:ELECTRON_CACHE -Recurse -File -ErrorAction SilentlyContinue).Count
$report=[ordered]@{checkedAt=(Get-Date).ToString('o');sourceRevision=$manifest.sourceRevision;bundleSha256=(Get-FileHash -LiteralPath $zip -Algorithm SHA256).Hash.ToLowerInvariant();installRoot=$InstallRoot;installExitCode=$installCode;nodeVersion=(& $node --version);npmVersion=(& $npm --version);sensitiveEnvironmentNamesRemoved=$removedSensitive.Count;npmCacheInitiallyEmpty=($initialNpmCache -eq 0);electronCacheInitiallyEmpty=($initialElectronCache -eq 0);npmCacheFileCountAfterInstall=$npmEntries;electronCacheFileCountAfterInstall=$electronEntries;electronExe=Join-Path $InstallRoot 'app/desktop/node_modules/electron/dist/electron.exe';electronPresent=(Test-Path -LiteralPath (Join-Path $InstallRoot 'app/desktop/node_modules/electron/dist/electron.exe') -PathType Leaf);userDataRoot=$env:LOCALAPPDATA}
$report | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath (Join-Path $EvidenceRoot 'clean-install-result.json') -Encoding utf8
if($installCode -ne 0){throw "Clean installer failed with exit $installCode; see sanitized install logs."}
$electronPath=$report.electronExe; $eversion=& $electronPath --version; if($LASTEXITCODE -ne 0){throw 'Installed Electron version probe failed.'}; Add-Content -LiteralPath (Join-Path $EvidenceRoot 'clean-install-metadata.log') -Value ('ELECTRON_VERSION='+$eversion)
Write-Output ('INSTALL_EXIT_CODE='+$installCode); Write-Output ('ELECTRON_VERSION='+$eversion); Write-Output ('INSTALL_ROOT='+$InstallRoot)
